#!/bin/bash

# Align paired-end reads

set -euo pipefail

if (( $# < 2 )); then
	echo "usage : $0 <prefix> <reference-fasta>" >&2
	exit 1
fi

# Prefix is $outdir/${I}_${J}_${K}/orig
fq=$1
bam=$2
ref=$3

# Assign output file name for r1 and r2
r1=$fq.r1.fq
r2=$fq.r2.fq


if [[ ! -f ${ref}.bwt ]]; then
	bwa index ${ref}
fi

# Define read group string for bwa
sm=${bam##*/}
rg="@RG\\tID:$sm\\tPU:$sm\\tSM:$sm\\tLB:$sm\\tPL:illumina"
# Align reads with bwa using r1 and r2 generated by csrsim.py along with read group string and reference
# The output is a BAM file: orig.bam; and it's index: orig.bai
bwa mem $ref $r1 $r2 -R $rg |
	samtools view -b > $bam.raw.bam
samtools sort $bam.raw.bam -o $bam.bam
rm $bam.raw.bam
samtools index $bam.bam

